{
  "name": "opencode-dynamic-custom-providers",
  "version": "2.2.0",
  "description": "Dynamic model discovery for OpenAI-compatible providers in OpenCode with models.dev enrichment",
  "type": "module",
  "main": "./dist/server.js",
  "types": "./dist/server.d.ts",
  "files": [
    "dist"
  ],
  "exports": {
    ".": {
      "types": "./dist/server.d.ts",
      "default": "./dist/server.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "default": "./dist/server.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.js"
    }
  },
  "scripts": {
    "build": "tsc",
    "test": "npm run build && node tests/security.test.mjs && node tests/discovery.test.mjs && node tests/commands.test.mjs && node tests/server.test.mjs && node tests/persist.test.mjs",
    "prepare": "npm run build",
    "prepublishOnly": "npm test"
  },
  "keywords": [
    "opencode",
    "plugin",
    "ai",
    "openai",
    "dynamic",
    "discovery",
    "models.dev"
  ],
  "author": "b3nw",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/b3nw/opencode-dynamic-custom-providers.git"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.14.0"
  },
  "devDependencies": {
    "@opencode-ai/sdk": "^1.14.0",
    "@opentui/solid": "^0.2.0",
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.14.0"
  },
  "engines": {
    "opencode": ">=1.14.0"
  }
}
